import React from 'react';
import { Box, Button, Card, CardContent, Grid, Stack, Typography } from '@mui/material';
import { OpenInNew as OpenInNewIcon } from '@mui/icons-material';
import { GOVERNMENT_INCENTIVE_SCHEMES } from '../../constants/governmentIncentiveSchemes';

const GovernmentSchemeBoard: React.FC = () => (
  <Box>
    <Typography variant="body1" sx={{ mb: 0.5 }}>
      These are public programmes. You apply on the government site.
    </Typography>
    <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720 }}>
      This workspace does not submit scheme applications and does not work with banks or other lenders.
      Use your target and reduction ideas as evidence when a portal asks for energy or emissions progress.
    </Typography>
    <Grid container spacing={2}>
      {GOVERNMENT_INCENTIVE_SCHEMES.map((scheme) => (
        <Grid item xs={12} md={6} key={scheme.id}>
          <Card variant="outlined" sx={{ height: '100%' }}>
            <CardContent>
              <Typography variant="overline" color="text.secondary">
                {scheme.owner}
              </Typography>
              <Typography variant="h6" sx={{ mb: 1 }}>
                {scheme.name}
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                {scheme.summary}
              </Typography>
              <Stack direction="row">
                <Button
                  component="a"
                  href={scheme.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  endIcon={<OpenInNewIcon />}
                  variant="outlined"
                  size="small"
                >
                  Open official site
                </Button>
              </Stack>
            </CardContent>
          </Card>
        </Grid>
      ))}
    </Grid>
  </Box>
);

export default GovernmentSchemeBoard;
